INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-05-training-005', 'p1b-m1-05-training', 'physics-b-1', 'p1b-m1', 2, '第 5 题', '一人造地球卫星绕地球作椭圆运动,近地点为A,远地点为B,A、B两点距地心分别为 $r _ { 1 } , r _ { 2 }$ ,设卫星质量为m,地球质量为M,万有引力常数为G。则卫星在A、B两点处的万有引力势能之差 $E _ { p B ^ { - } } E _ { p A }$ 为 ,动能之差$E _ { k B } – E _ { k A }$ 为', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-05-training/1742c89adc33d757e90e84df44ba7cd78a0d21f74d469695ba246debf45b358c.jpg', 1, '["填空题"]'::jsonb, '力学练习五.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
