INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-05-training-007', 'p1b-m1-05-training', 'physics-b-1', 'p1b-m1', 3, '第 7 题', '质量为 m 的子弹 A,以 $\\nu _ { 0 }$ 的速率水平地射入一静止在水平面上的质量为M 的 B内,A射入B后,B向前移动了S的距离后而停止,求： B与水平面间的摩擦系数; (2)木块对子弹所作的功 $W _ { 1 }$ ;
