INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-05-training-008', 'p1b-m1-05-training', 'physics-b-1', 'p1b-m1', 3, '第 8 题', '质量为 $m _ { 1 }$ 的A物与弹簧相连,弹簧劲度系数为k;另有一质量为 $m _ { 2 }$ 的B物通过轻绳与A物相连,两物体与水平面的摩擦系数为零。今以一恒力F将B物向右拉(如图所示),施力前弹簧处于自然长度,A、B两物均静止,且A、B间的轻绳绷直。求两物A、B系统受合力为零时的速度;
(2)上述过程中绳的拉力对物A所作的功,恒力F对物B所作的功。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-05-training/f26f892ae856d4c3c831545ee06ab08b8c65a3c9eb752ac745694b7bf914476d.jpg', 1, '["计算题"]'::jsonb, '力学练习五.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
