INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-002', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '如图所示,A、B 为两个相同的绕着轻绳的定滑轮。A 滑轮挂一质量为 M的物体,B滑轮受拉力 F,而且 $\\scriptstyle { F = M g }$ 。设 A、B两滑轮的角加速度分别为 $\\beta _ { \\mathrm { { A } } }$ 和 $\\beta _ { \\mathrm { B } }$ 不计滑轮轴的摩擦,则有', '["$\\\\beta _ { \\\\mathrm { { A } } } { = } \\\\beta _ { \\\\mathrm { { B } } }$","$\\\\beta _ { \\\\mathrm { { A } } } { > } \\\\beta _ { \\\\mathrm { { B } } }$","$\\\\beta _ { \\\\mathrm { { A } } } { < } \\\\beta _ { \\\\mathrm { { B } } }$","开始时 $\\\\beta _ { \\\\mathrm { { A } } } { = } \\\\beta _ { \\\\mathrm { { B } } }$ ,以后 $\\\\beta _ { \\\\mathrm { { A } } } { < } \\\\beta _ { \\\\mathrm { { B } } }$ 0"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-06-training/2c9b08b7b89e0b0f012c35a1273090ff58e71e6a13152cd067ca7ef95110049d.jpg', 1, '["选择题"]'::jsonb, '力学练习六.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-003', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '一绕中心轴转动的圆盘,角速度为 ${ \\pmb \\omega } _ { \\pmb _ { \\imath } }$ 若将它放在摩擦系数为 水平桌面上,问经过多长时间停下来？(已知圆盘质量为 m 半径为 R,绕轴的转动惯量为 $J = \\frac { 1 } { 2 } m R ^ { 2 } \\mathbf { \\Sigma } )$', '["$\\\\frac { 3 R } { 4 \\\\mu g }$","$\\\\frac { 5 R } { 4 \\\\mu g }$","$\\\\frac { 3 \\\\omega } { 4 R \\\\mu g }$","$\\\\frac { 3 R \\\\omega } { 4 \\\\mu g }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习六.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-004', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 2, '第 4 题', '一根均匀棒,长为 l,质量为 m,可绕通过其一端且与其垂直的固定轴在竖直面内自由转动。开始时棒静止在水平位置,当它自由下摆时,它的初角速度等于 \\_,初角加速度等于 。已知均匀棒对于通过其一端垂直于棒的轴的转动惯量为 ${ \\frac { 1 } { 3 } } m l ^ { 2 }$', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习六.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-005', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 2, '第 5 题', '如图,质量为 m 和 2m 的两个质点 A和 B,用一长为 L的轻质细杆相连,系统绕通过杆上 O点且与杆垂直的水平轴转动,已知 O点与 A点相距 2L/3,B点的线速度为v,且与杆垂直,则该系统对转轴的转动惯量大小为： ,杆的角速度为 ,在图示位置时刻,杆受的合力矩为 ,杆的角加速度为 0', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-06-training/9f4edfa3acf2ff0718e3ff9499a2901c00b4ddb89217c3d4e6d4f518b3cf722a.jpg', 1, '["填空题"]'::jsonb, '力学练习六.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-006', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 3, '第 6 题', '质量为m的物体悬于一条轻绳的一端,绳另一端绕在一轮轴的轴上,如图所示。轴水平且垂直于轮轴面,其半径为r , 整个装置架在光滑的固定轴承之上。当物体从静止释放后,在时间t 内下降了一段距离S。试求整个轮轴的转动惯量(用m、r、t 和S 表示)。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-06-training/051d57409f11372b21bfce7342d670adc400759565f4ead61a0cb4626700b284.jpg', 1, '["计算题"]'::jsonb, '力学练习六.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-06-training-007', 'p1b-m1-06-training', 'physics-b-1', 'p1b-m1', 3, '第 7 题', '如图所示,一个质量为 m 的物体与绕在定滑轮上的绳子相联,绳子质量可以忽略,它与定滑轮之间无滑动。假设定滑轮质量为 M、半径为R,其转动惯量为 $\\frac { 1 } { 2 } M R ^ { 2 }$ ,滑轮轴光滑。试求该物体由静止开始下落R的过程中,下落速度与时间的关系。 M', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-06-training/4067317c7cda28aaf79cc3e8ed7af8597fb73ae2fa61ed40788151e31bb3913b.jpg', 1, '["计算题"]'::jsonb, '力学练习六.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-001', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '一水平圆盘可绕通过其中心的固定竖直轴转动,盘上站着一个人。把人和圆盘取作系统,当此人在盘上随意走动时,若忽略轴的摩擦,此系统', '["动量守恒","机械能守恒","对转轴的角动量守恒","动量、机械能和角动量都守恒"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习七.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-002', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '如图所示,一匀质细杆可绕通过上端与杆垂直的水平光滑固定轴 旋转,初始状态为静止悬挂。现有一个小球自左方水平打击细杆。 设小球与细杆之间为非弹性碰撞,则在碰撞过程中对细杆与小球这一系统', '["只有机械能守恒","只有动量守恒","只有对转轴O的角动量守恒","机械能、动量和角动量均守恒。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-07-training/43ec6662ef75c0d98fdc5a04798a1558b5aa2c97b81b1f0f76fdd08d815dd61c.jpg', 1, '["选择题"]'::jsonb, '力学练习七.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-003', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '一个半径为 R=20.0cm,质量为 m 的均匀薄圆盘,竖直地立放在粗糙的水平桌面上。开始时处于静止状态,而后薄圆盘受到轻微扰动而绕过接触点的某一轴转动最终倒下,已知圆盘对该轴的转动惯量为 $5 \\mathrm { m } R ^ { 2 } / 4$ 。则圆盘平面与桌面碰撞前(即圆盘平面在水平位置)时质心速度的大小为 $\\nu _ { \\mathrm { c } } =$', '["(两位有效数字,重力加速度 $g { = } 9 . 8 0 \\\\mathrm { m } / \\\\mathrm { s } _ { 2 } )$1.3m/s","1.8m/s","2.2m/s","$2 . 5 \\\\mathrm { m } / \\\\mathrm { s } .$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习七.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-004', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 0, '第 4 题', '一人站在轴上无摩擦的旋转平台上,平台以 $\\omega _ { \\mathrm { i } } = 2 \\pi$ $r a d \\textit { \\textbf { / s } }$ 的角速度旋转,这时他的双臂水平伸直,并且两手都握着重物,整个系统的转动惯量是 $J _ { 1 } { = } 6 . 0 0 \\mathrm { k g } { \\cdot } \\mathrm { m } ^ { 2 }$ 。如果他将双手收回,系统的转动惯量减小到 $J _ { 2 } { = } 2 . 0 0$ $\\mathrm { k g } \\cdot \\mathrm { m } ^ { 2 }$ ,则系统的转动动能增量为', '["237J","400J","20J","135J"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习七.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-005', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 0, '第 5 题', '一根长为l、质量为M的匀质棒自由悬挂于通过其上端的光滑水平轴上。现有一质量为m的子弹以水平速度 $\\nu _ { 0 }$ 射向棒的中心,并以 $\\nu _ { 0 } / 2$ 的水平速度穿出棒,此后棒的最大偏转角恰为 $9 0 ^ { \\circ }$ ,则 $\\nu _ { 0 }$ 的大小为', '["$\\\\frac { 4 M } { m } \\\\sqrt { \\\\frac { g l } { 3 } }$","$\\\\sqrt { \\\\frac { g l } { 2 } }$","$\\\\frac { 2 M } { m } \\\\sqrt { g l }$","$\\\\frac { 1 6 M ^ { 2 } g l } { 3 m ^ { 2 } }$ o"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习七.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-006', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 2, '第 6 题', '如图所示,A、B 两飞轮的轴杆在一条直线上,并可用摩擦啮合器 C使它们连结。开始时 A C BB 轮静止,A 轮以角速度 $\\omega _ { A }$ 转动,设在啮合过程中两飞轮不受其它力矩的作用。当两轮连结在一起后,共同的角速度为 $\\omega$ 。若 A轮的转动惯量为 $J _ { \\mathrm { A } }$ ,则 轮的转动惯 $J _ { \\mathrm { B } } { = }$ C', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习七.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-007', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 2, '第 7 题', '一半径为 0.1m 的飞轮能绕水平轴在铅直面内作无摩擦的自由转动,其转动惯量$\\scriptstyle \\mathbf { J } = 2 \\times 1 0 ^ { - 2 } ( \\mathbf { k g } \\cdot \\mathbf { m } ^ { 2 } )$ ,由静止开始受一作用在轮缘上,方向始终与切线一致的变力作用,其大小为 $F = 0 . 5 t \\quad \\left( \\mathrm { N } \\right)$ ,则受力后一秒末的角速度为', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '力学练习七.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-07-training-008', 'p1b-m1-07-training', 'physics-b-1', 'p1b-m1', 3, '第 8 题', '一根放在水平光滑桌面上的匀质棒,可绕通过其一端的竖直固定光滑轴 O 转动。棒的质量为 $m { = } 1 . 5 \\mathrm { k g }$ ,长度为 l=1.0m,对轴的转动惯量为$J { = } m l ^ { 2 } / 3$ 。初始时棒静止。今有一水平运动的子弹垂直地射入棒的另一端,并留在棒中,如图所示。子弹的质量为 $\\mathrm { m } { = } 0 . 0 2 \\mathrm { k g }$ ,速率为 v=400m/s。试问：棒开始和子弹一起转动时角速度 有多大？
(2)若棒转动时受到大小为 $\\textstyle M _ { \\mathrm { r } } = 4 . 0 \\mathrm { N } \\cdot \\mathrm { m }$ 恒定阻力矩作用,棒能转过多大的角度θ？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m1-07-training/447fae5f824e760711941e2e4f7d6f7afb00fe369ac80f519abd2e86c072ebb3.jpg', 1, '["计算题"]'::jsonb, '力学练习七.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-001', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '某质点作直线运动的运动学方程为 $x=3 t-5 t^{3}+6$ (SI)，则该质点作', '["匀加速直线运动，加速度沿 x 轴正方向","匀加速直线运动，加速度沿x轴负方向","变加速直线运动，加速度沿x轴正方向","变加速直线运动，加速度沿x轴负方向"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-002', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '某物体的运动规律为 $\\frac{dv}{d t}=-k v^{2}t$ ，式中的k 为大于零的常量。当t = 0时，初速为$v_{0}$ ，则速度v 与时间t 的函数关系是', '["$v=\\\\frac{1}{2}k t^{2}+v_{0}$","$v=-\\\\frac{1}{2}k t^{2}+v_{0}$","$\\\\frac{1}{v}=\\\\frac{k t^{2}}{2}+\\\\frac{1}{v_{0}}$","$\\\\frac{1}{v}=-\\\\frac{k t^{2}}{2}+\\\\frac{1}{v_{0}}$"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-003', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '一质点沿x方向运动，其加速度随时间变化关系为a=3+2t (SI)，如果初始时质点的速度 $v_{0}$ 为5m/s ， 则在t = 4s 时刻质点的速度v =', '["15m/s","23m/s","33m/s","45m/s"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-004', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 4 题', '一质点在平面上作一般曲线运动，其瞬时速度为$\\vec{v}$ ，瞬时速率为v ，某一时间内的平均速度为 $\\overline{\\vec{v}}$ ，平均速率为v ，它们之间的关系必定有：', '["$\\\\left| \\\\vec{v}\\\\right|=v , \\\\left| \\\\overline{\\\\vec{v}}\\\\right|=\\\\overline{v}$","$\\\\left| \\\\vec{v}\\\\right| \\\\neq v , \\\\left| \\\\overline{\\\\vec{v}}\\\\right|=\\\\overline{v}$","$\\\\left| \\\\bar{v}\\\\right| \\\\neq v , \\\\ \\\\left| \\\\overline{\\\\bar{v}}\\\\right| \\\\neq \\\\overline{v}$","$\\\\left| \\\\vec{v}\\\\right|=v , \\\\left| \\\\overline{\\\\vec{v}}\\\\right| \\\\neq \\\\overline{v}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-005', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 5 题', '质量为0.10 kg的质点，由静止开始沿曲线 $\\vec{r}=\\frac{5}{3}t^{3}\\vec{i}+2 \\vec{j}$ (SI)运动，则在t =0到t = 2s时间内，作用在该质点上的合外力所做的功为', '["$\\\\frac{5}{4}\\\\mathrm{J}$","20J","$\\\\frac{75}{4}\\\\mathrm{J}$","40J"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-006', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 6 题', '如图所示，子弹射入放在水平光滑地面上静止的木块而不穿出．以地面为参考系，下列说法中正确的说法是', '["子弹的动能转变为木块的动能","子弹─木块系统的机械能守恒","子弹动能的减少等于子弹克服木块阻力所作的功","子弹克服木块阻力所作的功等于这一过程中产生的热"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q006.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-007', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 7 题', '一质量为m 的滑块，由静止开始沿着 1/4 圆弧形光滑的木槽滑下。设木槽的质量也是m。槽的圆半径为R，放在光滑水平地面上，如图所示。则滑块离开槽时的速度是', '["$\\\\sqrt{2Rg}$","$2 \\\\sqrt{Rg}$","$\\\\sqrt{Rg}$ ：","$\\\\frac{1}{2}\\\\sqrt{Rg}$"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q007.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-008', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 8 题', '一均匀细杆原来静止放在光滑的水平面上，现在其一端给予一垂直于杆身的水平方向的打击，此后杆的运动情况是：', '["杆沿力的方向平动","杆绕其未受打击的端点转动","杆的质心沿打击力的方向运动，杆又绕质心转动","杆的质心不动，而杆绕质心转动"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-009', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 9 题', '如图所示，一个小物体，位于光滑的水平桌面上，与一绳的一端相连结，绳的另一端穿过桌面中心的小孔O. 该物体原以角速度ω在半径为R的圆周上绕O旋转，今将绳从小孔缓慢往下拉．则物体', '["动能不变，动量改变;","动量不变，动能改变;","角动量不变，动量不变;","角动量改变，动量改变;","角动量不变，动能、动量都改变"]'::jsonb, '4', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q009.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-010', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 10 题', '人造地球卫星，绕地球作椭圆轨道运动，地球在椭圆的一个焦点上，则卫星的', '["动量不守恒，动能守恒","动量守恒，动能不守恒","对地心的角动量守恒，动能不守恒","对地心的角动量不守恒，动能守恒"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-011', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 11 题', '一圆盘绕过盘心且与盘面垂直的光滑固定轴O以角速度ω按图示方向转动.若如图所示的情况那样，将两个大小相等方向相反但不在同一条直线的力F沿盘面同时作用到圆盘上，则圆盘的角速度', '["必然增大;","必然减少;","不会改变;","如何变化，不能确定"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q011.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-012', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 12 题', '均匀细棒OA可绕通过其一端O而与棒垂直的水平固定光滑轴转动，如图所示．今使棒从水平位置由静止开始自由下落，在棒摆动到竖直位置的过程中，下述说法哪一种是正确的？', '["角速度从小到大，角加速度从大到小;","角速度从小到大，角加速度从小到大;","角速度从大到小，角加速度从大到小;","角速度从大到小，角加速度从小到大"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q012.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-013', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 13 题', '图(a)为一绳长为l 、质量为m 的单摆。图(b)为一长度为l、质量m为能绕水平固定轴O自由转动的匀质细棒。现将单摆和细棒同时从与竖直线成θ 角度的位置由静止释放。若运动到竖直位置时，单摆、细棒角速度分别以 $\\omega_{1}, \\ \\omega_{2}$ 表示。则：', '["$\\\\omega_{1}{=}2 \\\\omega_{2}$","$\\\\omega_{1}{=}\\\\omega_{2}$","$\\\\omega_{1}=\\\\frac{2}{3}\\\\omega_{2}$","${\\\\omega}_{1}=\\\\sqrt{\\\\frac{2}{3}}\\\\,{\\\\omega}_{2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q013.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-014', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 14 题', '一轻绳跨过一具有水平光滑轴、质量为的定滑轮，绳的两端分别悬有质量为 $m_{1}$ 和 $m_{2}$ 的物体 $( m_{1}<m_{2})$ ，如图所示。绳与轮之间无相对滑动。若某时刻滑轮沿逆时针方向转动，则绳中的张力', '["处处相等","左边大于右边","右边大于左边","哪边大无法判断"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q014.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-015', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 15 题', '一自由悬挂的匀质细棒 AB，可绕 A 端在竖直平面内自由转动，现给 B 端一初速$\\mathbf{V}_{0},$ ，则棒在向上转动过程中仅就大小而言', '["角速度不断减小，角加速度不断减少","角速度不断减小，角加速度不断增加","角速度不断减小，角加速度不变","所受力矩越来越大，角速度也越来越大"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-016', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 16 题', '一长为l，质量为m 的匀质细棒，绕一端作匀速转动，其中心处的速率为v，则细棒的转动动能为', '["$\\\\mathrm{m}\\\\mathrm{v}^{2}/2$","$2 \\\\mathrm{mv}^{2}/3$","$\\\\mathrm{m}\\\\mathrm{v}^{2}/6$","$\\\\mathrm{mv}^{2}/24$"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-017', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 0, '第 17 题', '光滑的水平桌面上，有一长为 2L、质量为m的匀质细杆，可绕过其中点且垂直于杆的竖直光滑固定轴O自由转动，其转动惯量为 $\\frac{1}{3}mL^{2}$ ，起初杆静止．桌面上有两个质量均为m的小球，各自在垂直于杆的方向上，正对着杆的一端，以相同速率v相向运动，如图所示．当两小球同时与杆的两个端点发生完全非弹性碰撞后，就与杆粘在一起转动，则这一系统碰撞后的转动角速度应为', '["$\\\\frac{2v}{3 L}$","$\\\\frac{4v}{5 L}$","$\\\\frac{6v}{7 L}$","$\\\\frac{8v}{9 L}$ 俯视图"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/q017.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-018', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 18 题', '质点的运动方程 $\\vec{r}=\\left( t-\\frac{t^{2}}{2}\\right) \\vec{i}+\\left( 5-3 t+\\frac{t^{3}}{3}\\right) \\vec{j}$ (SI)，当 $t=2\\,\\mathrm{s}$ 时，其加速度 $\\vec{a}=$', '[]'::jsonb, '$10\\vec i+18\\vec j\\ \\mathrm{m/s^2}$', '[]'::jsonb, NULL, NULL, NULL, '对 $\\vec r$ 求二阶导数：$\\vec a=\\frac{\\mathrm d^2\\vec r}{\\mathrm dt^2}=10\\vec i+9t\\vec j$；代入 $t=2\\,\\mathrm{s}$ 得 $\\vec a=10\\vec i+18\\vec j\\ \\mathrm{m/s^2}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-019', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 19 题', '在如图所示的装置中，两个定滑轮与绳的质量以及滑轮与其轴之间的摩擦都可忽略不计，绳子不可伸长， $m_{1}$ 与平面之间的摩擦也可不计，在水平外力 F 的作用下，物体 $m_{1}$ 与 $m_{2}$ 的加速度 a＝ _，绳中的张力 T＝', '[]'::jsonb, '$\\frac{F}{m_1+m_2}$; $\\frac{m_2F}{m_1+m_2}$', '[]'::jsonb, NULL, NULL, NULL, '整体：$F=(m_1+m_2)a$，得 $a=F/(m_1+m_2)$。对 $m_2$：$T=m_2a=m_2F/(m_1+m_2)$。', NULL, NULL, '/physics/q019.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-020', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 20 题', '质量为 m 子弹以速度 $v_{0}$ 水平射入沙土中，设子弹所受阻力与速度成正比，比例系数为 k，忽略子弹的重力，求：(1)子弹射入沙土后,速度随时间变化的函数关系式 _；(2)子弹射入沙土的最大深度。', '[]'::jsonb, '$v=v_0e^{-kt/m}$; $\\frac{mv_0}{k}$', '[]'::jsonb, NULL, NULL, NULL, '由 $m\\frac{dv}{dt}=-kv$ 积分得 $v=v_0e^{-kt/m}$。最大深度 $x=\\int_0^\\infty v\\,dt=mv_0/k$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-021', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 21 题', '一颗子弹在枪筒里前进时所受的合力大小为 $F=400-\\frac{4\\times10^{5}}{3}t$ (SI) ，子弹从枪口射出时的速率为 300 m/s。假设子弹离开枪口时合力刚好为零，则 (1)子弹走完枪筒全长所用的时间t = _； (2)子弹在枪筒中所受力的冲量I =； (3)子弹的质量m= 。', '[]'::jsonb, '$3\\times10^{-3}\\ \\mathrm{s}$; $0.6\\ \\mathrm{N\\cdot s}$; $2\\ \\mathrm{g}$', '[]'::jsonb, NULL, NULL, NULL, '令 $F=0$ 得 $t=3\\times10^{-3}\\,\\mathrm{s}$。冲量 $I=\\int_0^t F\\,dt=400t-\\frac{2\\times10^5}{3}t^2=0.6\\,\\mathrm{N\\cdot s}$。由 $I=mv$ 得 $m=I/v=0.002\\,\\mathrm{kg}=2\\,\\mathrm{g}$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
